config.script:
// laudo_aviso — agente `script`. Comportamento = ESTE arquivo (DADO), nunca código de serviço.
//
// Gatilho: o resultado de um exame foi LIBERADO ao paciente (evento `exames.resultado_disponivel`), seja pela
// médica na tela, seja pelo agente "Liberar laudo automaticamente". O evento traz só ids: `subject.exame_id`
// e `subject.cliente_id`.
//
// Ação: 1 intenção de envio na mensageria (`enviar_intencao`) com o template `config.template_slug`
// ("Há um resultado novo no portal"), SEM variáveis. Modo `failover`: WhatsApp pelo modelo aprovado quando
// houver; senão e-mail. A mensageria descobre o contato do paciente sozinha (o agente não lê o cadastro).
//
// LGPD: o NOME/tipo do exame nunca vai no texto, nas variáveis, no log nem no resumo (tipo de exame + paciente
// = dado de saúde). O agente nem recebe o nome: só ids.
//
// Sem duplicar: chave `resultado_exame:<cliente_id>:<exame_id>` (ids opacos, sem dado pessoal). O mesmo exame
// liberado de novo (ou o evento reentregue) volta `deduplicado` — o paciente recebe 1 aviso por exame.
//
// Falha visível (anti falso-verde): envio que volta com erro ou com status fora de aceito/deduplicado/agendado
// conta como FALHA: log WARNING e `acao_bloqueada` no resumo — nunca vira "enviado".
//
// Injetados: event, config, context, call() -> {ok,status_code,body}, log(), result().

var cfg = config || {};
var template = String(cfg.template_slug || 'resultado_exame').trim();
var sub = (event && event.subject) || {};
var clienteId = sub.cliente_id ? String(sub.cliente_id) : '';
var exameId = sub.exame_id ? String(sub.exame_id) : '';

function unwrap(r) {
  if (!r || !r.ok) return null;
  var b = r.body;
  return (b && b.data !== undefined) ? b.data : b;
}

if (!clienteId || !exameId) {
  var motivo = !clienteId ? 'sem_paciente' : 'sem_exame';
  log('laudo_aviso: evento sem ' + (!clienteId ? 'paciente' : 'exame') + ' — nada a enviar');
  result({ skip: motivo });
  return { skip: motivo };
}

var r = call('enviar_intencao', {
  destinatario_id: clienteId,
  modo_entrega: 'failover',
  template_slug: template,
  variaveis: {},
  origem_ms: 'agentes',
  referencia_tipo: 'exame_resultado',
  referencia_id: exameId,
  idempotency_key: 'resultado_exame:' + clienteId + ':' + exameId
});
var body = unwrap(r);
var st = body && body.status;
if (r && r.ok && (st === 'aceito' || st === 'deduplicado' || st === 'agendado')) {
  var resumo = { status: st, enviado: st === 'aceito', deduplicado: st === 'deduplicado', agendado: st === 'agendado' };
  log('laudo_aviso: aviso ao paciente ' + (st === 'aceito' ? 'enviado' : (st === 'deduplicado' ? 'já enviado antes' : 'agendado')));
  result(resumo);
  return { ok: true, status: st };
}

var http = (r && r.status_code) || null;
log('laudo_aviso: FALHA ao pedir o aviso (exame ' + exameId + ', HTTP ' + (http || '?') + ', status ' + (st || '-') + ')',
  'warning');
result({ acao_bloqueada: true, etapa: 'enviar_intencao', http: http, status: st || null, enviado: false });
return { ok: false, erro: 'enviar_falhou', http: http, status: st || null };
